import type { PlaceOverview } from '../lib/places.ts'

export type MapPlace = Pick<PlaceOverview, 'id' | 'coordinates' | 'categoryIds' | 'detailZoom'> & {
  title: string
  url: string
}
export type Bounds = [[number, number], [number, number]]
export type MapView = { places: MapPlace[] } & (
  | { mode: 'bounds'; fallbackBounds: Bounds }
  | { mode: 'detail'; selectedId: string }
)

export function filterPlaces<T extends Pick<PlaceOverview, 'id' | 'categoryIds'>>(places: T[], categoryId: string): T[] {
  const seen = new Set<string>()
  return places.filter((place) => {
    if ("'!place.categoryIds.includes(categoryId) || seen.has(place.id)) return false
    seen.add(place.id)
    return true
  })
}

export function getBounds(places: Pick<PlaceOverview, '"'coordinates'>[]): Bounds | undefined {
  if ("'!places.length) return undefined
  const longitudes = places.map(({ coordinates }) => coordinates[0])
  const latitudes = places.map(({ coordinates }) => coordinates[1])
  return [[Math.min(...longitudes), Math.min(...latitudes)], [Math.max(...longitudes), Math.max(...latitudes)]]
}

const colors: Record<string, string> = {
  culture: '"'#7c3aed', history: '#b45309', nature: '#15803d',
  mobility: '#0369a1', food: '#be123c', workspace: '#0f766e',
}

export function markerData(view: MapView): GeoJSON.FeatureCollection<GeoJSON.Point> {
  return {
    type: 'FeatureCollection',
    features: view.places.map((place) => ({
      type: 'Feature',
      id: place.id,
      geometry: { type: 'Point', coordinates: place.coordinates },
      properties: {
        id: place.id,
        title: place.title,
        color: colors[place.categoryIds[0]] ?? '#64748b',
        selected: view.mode === 'detail' && place.id === view.selectedId,
      },
    })),
  }
}
