 def __init__(self,path):
  super().__init__();self.config=None;self.urls=[];self.active=[];self.feed(path.read_text())
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'data-map-config' in a:self.config=json.loads(a['data-map-config'])
  if tag=='a':
   self.urls.append(a.get('href',''))
   if a.get('aria-current')=='page':self.active.append(a.get('href',''))
places=json.loads(Path('public/data/markers/overview.json').read_text())
categories=json.loads(Path('public/data/categories.json').read_text())
for locale in ['en','de']:
 prefix='' if locale=='en' else 'de/'
 base='/astro-maplibre/'+prefix
 for category in categories:
  page=Page(Path('dist')/prefix/'category'/category['id']/'index.html')
  expected=[p['id'] for p in places if category['id'] in p['categoryIds']]
  assert [p['id'] for p in page.config['places']]==expected
  assert base+'category/'+category['id']+'/' in page.active
  for p in page.config['places']:
   assert p['url']==base+'place/'+p['id']+'/' and p['url'] in page.urls
 for place in places:
  page=Page(Path('dist')/prefix/'place'/place['id']/'index.html')
  assert page.config['mode']=='detail' and page.config['selectedId']==place['id']
  assert [p['id'] for p in page.config['places']]==[place['id']]
  assert page.config['places'][0]['title']==place['title'][locale]
 for view in ['map','map/overview']:
  page=Page(Path('dist')/prefix/view/'index.html')
  assert len(page.config['places'])==len(places)
for p in Path('dist/_astro').glob('*.js'):
